INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N033-12','CN0063','W01B2S22','逐样本监测保全','表2-9、2-17、2-18、2-19，印刷页35–36、42–44','原有最大日均保留，本批补单次原始样本，ND与低于检出限分别保留。表2-18回用水日期8/13、8/14与叙述8/12、8/13不一致，按表头；生活SS表日均111而叙述11，保留表数据。总碱度限值不直接套单独重碳酸盐。','WEB_PRIMARY','公开正文或表格摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N033-13','CN0063','W01B2S22','验收合规口径及膜范围','表2-16至2-19','允许年排水3862t/a不是实排；总氮表质量0.0707与控制0.012但表称达标，存在原文差异，暂不独立判定合规。再生站30t/h为设计能力，2024验收回用水实际样本，不表示2026现行工况。此前19000t/a验收规模不是实际年处理量；纯水浓水与工业RO浓水分开。','WEB_PRIMARY','公开正文或表格摘录，非原件归档','2026-11-27');
